def _price_tier(price: int | None) -> str | None:
    if price is None or price == 0:
        return None
    if price < 300000:
        return 'budget'
    elif price < 800000:
        return 'mid'
    elif price < 2000000:
        return 'premium'
    else:
        return 'luxury'
